/// <summary>
/// Purchase order number parameter
/// </summary>
/// <param name = "_purchId">purchId</param>
/// <returns>purchId</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@SYS25204")),
    SysOperationControlVisibilityAttribute(false)

]
public PurchId parmPurchId(PurchId _purchId = purchId)
{
    purchId = _purchId;

    return purchId;
}

